import{_ as i,l as n,o as e,c as s,v as o,p as l,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"循环不变式","description":"","frontmatter":{"title":"循环不变式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/loop-invariant.md","filePath":"cs/loop-invariant.md","lastUpdated":1789023840000}'),h={name:"cs/loop-invariant.md"};function E(m,a,B,_,A,u){const r=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="循环不变式" tabindex="-1">循环不变式 <a class="header-anchor" href="#循环不变式" aria-label="Permalink to &quot;循环不变式&quot;">​</a></h1><div class="epigraph"><p>若一条断言在进入循环前成立，每轮保持，终止时又推出目标，则循环做对了它该做的事。</p><footer>—— 据 Floyd, Assigning Meanings to Programs, 1967；Hoare, An Axiomatic Basis for Computer Programming, 1969 整理</footer></div><p>上一课<a href="/cs/planar-graph">平面图直觉</a>给了图表示一课的边界：何时平面、何时不必。数据结构课到此结束：对象、代价和表示都齐了。本课不重画邻接表，也不从「算法是什么」另起。缺口是：图和数组上的过程多数是<strong>循环</strong>，正确性不能只靠跑几个例子。本课只交出循环不变式；<a href="/cs/asymptotic-notation">渐近记号</a>已经有了，时间另算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一段 <code>for</code> 把数组左段排好、或把距离数组逐步改紧，肉眼看「好像对」。换输入、换边界，断言就散。缺口不是新的数据结构，而是把循环切成可归纳的三截：<strong>初始化</strong>进入前成立，<strong>保持</strong>每轮体执行后仍成立，<strong>终止</strong>退出时不变式加上循环条件的否定推出后置条件。</p><p>没有这三截，后课插入排序、Dijkstra 的「已确定集合」都只能口头讲。本课不引入霍尔三元组的全部演算，只要求：循环有一条关于部分结果的断言，且它可归纳。</p><h3 id="不变式不是循环条件" tabindex="-1">不变式不是循环条件 <a class="header-anchor" href="#不变式不是循环条件" aria-label="Permalink to &quot;不变式不是循环条件&quot;">​</a></h3><p>循环条件回答「还要不要再转」；不变式回答「到这一步，哪些已经对了」。两者同时成立才推出目标。把「<code>i &lt; n</code>」当成不变式，终止时什么也推不出。</p><p><span class="marginnote">Floyd 在框图节点上贴断言；Hoare 把 <code>{P} S {Q}</code> 写成推理规则。CLRS 第 2 章用插入排序当第一份作业：左段已排序。本课沿这条线，不把程序逻辑做成独立课程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选定循环变量（下标、已处理前缀、已确定顶点集）。写出：第 \\(i\\) 轮开始时，前缀或集合 \\(S\\) 满足性质 \\(I\\)。证明进入时 \\(I\\) 真；一轮只动允许动的那一块，动完 \\(I\\) 仍真；退出时 \\(\\neg C \\land I\\) 给出输出约定。</p>',11)),(e(),l(c,null,{default:t(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INIT%5B%22%E5%88%9D%E5%A7%8B%E5%8C%96%EF%BC%9AI%20%E6%88%90%E7%AB%8B%22%5D%20--%3E%20BODY%5B%22%E5%BE%AA%E7%8E%AF%E4%BD%93%EF%BC%9A%E4%BF%9D%E6%8C%81%20I%22%5D%0A%20%20BODY%20--%3E%20TEST%5B%22%E6%9D%A1%E4%BB%B6%20C%EF%BC%9F%22%5D%0A%20%20TEST%20--%3E%7C%22%E8%BF%98%E8%BD%AC%22%7C%20BODY%0A%20%20TEST%20--%3E%7C%22%E9%80%80%E5%87%BA%22%7C%20EXIT%5B%22%C2%ACC%20%E4%B8%94%20I%20%E2%87%92%20%E5%90%8E%E7%BD%AE%E6%9D%A1%E4%BB%B6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>归纳法在<a href="/cs/mathematical-induction">数学归纳</a>已有。这里的归纳指标是轮数，不是「对 \\(n\\) 归纳整个程序」。递归过程的正确性可以另写递归不变式；本课先钉迭代。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了不变式，修改循环时知道什么不能碰：破坏 \\(I\\) 的赋值必须补一条恢复。后课分治把问题切成子问题，正确性改走递归假设；本课的循环是同一层对象上的逐步扩大。两者会在归并、快排里交替出现，不要混成一句「都是归纳」。</p><p>不变式也可以带资源：已用比较次数、已松弛的边。那是分析，不是正确性本身。本课只要求部分结果为真；<a href="/cs/master-theorem">主定理</a>才处理递归式的渐近。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不变式不自动给出终止。要另证：某个非负势函数每轮严格下降，或循环变量有界递增。也不处理并发：多线程下「看起来保持」可以对交错失败。本课默认顺序执行。</p><p>后课默认：写一个迭代算法，先给出不变式再谈 \\(\\Theta\\)。插入、堆排、BFS 层、Dijkstra 的 \\(S\\)，都是本课的实例，不再从 Floyd 重讲。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>循环正确性 = 初始化 + 保持 + 终止时推出后置条件。</li><li>不变式描述部分结果，不是循环条件本身。</li><li>终止要另证；本课不处理并发。</li><li>出处：Floyd, 1967；Hoare, 1969；Cormen, Leiserson, Rivest and Stein, <em>Introduction to Algorithms</em> 第 2 章。</li></ul>',9))])}const T=i(h,[["render",E]]);export{C as __pageData,T as default};
